SELECT  FROM sol_preparation_item_waiver
WHERE tenant_id = #{query.tenantId}
  AND preparation_id = #{query.preparationId}
  AND item_id = #{query.itemId}
  AND id = #{query.waiverId}
FOR UPDATE

SELECT  FROM sol_preparation_item_waiver
WHERE tenant_id = #{query.tenantId}
  AND preparation_id = #{query.preparationId}
ORDER BY item_id ASC, waiver_no ASC, id ASC
FOR UPDATE

SELECT  FROM sol_preparation_item_waiver
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND item_code = #{query.itemCode}



        AND (waiver_no > #{query.cursorWaiverNo}
            OR (waiver_no = #{query.cursorWaiverNo} AND id > #{query.cursorId}))

    AND 1 = 0

ORDER BY waiver_no ASC, id ASC
LIMIT #{query.limit}

mapper.update:
UPDATE sol_preparation_item_waiver
SET status_code = #{update.statusCode},
    submitted_at = #{update.submittedAt},
    decided_by = #{update.decidedBy},
    decided_at = #{update.decidedAt},
    decision_opinion = #{update.decisionOpinion},
    withdrawn_at = #{update.withdrawnAt},
    updater = #{update.updater},
    update_time = CURRENT_TIMESTAMP(3),
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND preparation_id = #{update.preparationId}
  AND item_id = #{update.itemId}
  AND id = #{update.waiverId}
  AND version = #{update.expectedVersion}
  AND status_code = #{update.expectedStatusCode}
